-- Guarded correction of published educational drug cards. No private data.
DO $clinical$
DECLARE existing jsonb;
BEGIN
  SELECT jsonb_build_object('key_warning', d.key_warning, 'adult_bolus_dose', d.adult_bolus_dose, 'dosing', d.dosing, 'preparation', d.preparation, 'contraindications', d.contraindications, 'sources', d.sources) INTO STRICT existing FROM public.drugs AS d WHERE d.id='182e4e9d-b8af-4e8c-a119-bfbafda8fb3f'::uuid AND d.slug='desmopressin' FOR UPDATE;
  IF existing = '{"key_warning":"Fluid management depends on the indication. Excess water while antidiuresis is active can cause hyponatraemia. In known cranial diabetes insipidus, interruption of desmopressin or loss of access to water can cause life-threatening dehydration and hypernatraemia. Follow the individual endocrine fluid plan.","adult_bolus_dose":"The named injection (emc 5447) gives 1–4 micrograms once daily IV, IM or SC as the usual adult central-diabetes-insipidus regimen, individualised to response. See dosing for the distinct decompensated inpatient pathway.\nHaemostatic use is a separate specialist indication. Named UK DDAVP 4 micrograms/mL injection (emc 5447) specifies 0.4 micrograms/kg by IV infusion over 20 minutes for selected responsive patients with mild–moderate haemophilia or von Willebrand disease undergoing surgery or after trauma. Use the regimen selected by haematology, with factor response, sodium and fluid-balance monitoring. It is contraindicated for haemostasis in type 2B von Willebrand disease.","dosing":"Central diabetes insipidus (AVP deficiency): when a patient is alert with intact thirst and can safely drink, provide access to water and continue their agreed desmopressin regimen. A patient unable to drink, or with decompensated disease, needs an individual fluid plan, serial sodium and urine output, and urgent endocrine input. Correct circulatory volume depletion first. During resuscitation the Society for Endocrinology recommends sodium measurement every 4 hours. For known disease with excessive dilute urine, it describes 1–2 micrograms IV or IM with close assessment before any repeat dose.\nHaemostatic use is a separate specialist indication. Named UK DDAVP 4 micrograms/mL injection (emc 5447) specifies 0.4 micrograms/kg by IV infusion over 20 minutes for selected responsive patients with mild–moderate haemophilia or von Willebrand disease undergoing surgery or after trauma. Use the regimen selected by haematology, with factor response, sodium and fluid-balance monitoring. It is contraindicated for haemostasis in type 2B von Willebrand disease.\nOral tablets, sublingual melts and injections have different strengths, doses and uses. For nocturnal enuresis use the exact oral-product instructions for bedtime dosing and fluid restriction. Never convert numerical milligram, microgram or route doses directly.","preparation":"For the named UK 4 micrograms/mL DDAVP injection and its labelled haemostatic indication, dilute the selected dose in 50 mL sodium chloride 0.9% and infuse over 20 minutes. Follow the haematology prescription. The separate central-diabetes-insipidus regimen is titrated to fluid balance, serum sodium and urine output.","contraindications":"The named DDAVP injection lists hypersensitivity, habitual/psychogenic polydipsia, a history of unstable angina, cardiac insufficiency or other conditions requiring diuretics, known hyponatraemia and SIADH. For haemostatic use it also lists type 2B von Willebrand disease. Oral formulations have their own renal and age restrictions.","sources":[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Desmopressin (DDAVP) — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=desmopressin"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Desmopressin (DDAVP) — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=desmopressin"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Desmopressin (DDAVP) — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=desmopressin"},{"accessed":"2026-11-01","publisher":"electronic Medicines Compendium (emc), Datapharm","reviewNote":"Selected formulation, route and population only. Other presentations, storage and treatment doses are not verified; no current stock availability certification.","scope":"4micrograms/mL desmopressin acetate equivalent to3.56micrograms/mL desmopressin, IV/IM/SC indication-specific adults/children/infants; oral forms not covered.","sections":["1","2","3","4.1","4.2"],"title":"DDAVP/Desmopressin Injection — UK SmPC","url":"https://www.medicines.org.uk/emc/product/5447/smpc"},{"title":"Inpatient management of cranial diabetes insipidus: access to water, fluid replacement and parenteral desmopressin","url":"https://doi.org/10.1530/EC-18-0154","publisher":"Society for Endocrinology","accessed":"2026-11-19"}]}'::jsonb THEN
    NULL;
  ELSIF existing = '{"key_warning":"Strict fluid restriction and regular monitoring of serum sodium are essential due to the risk of severe hyponatraemia and water intoxication.","adult_bolus_dose":"• Cranial Diabetes Insipidus (IV/IM/SC): 1–4 micrograms daily in 1–2 divided doses.\n• Haemostasis (IV): 0.3 micrograms/kg (maximum 20 micrograms) infused over 15–30 minutes.","dosing":"• Cranial Diabetes Insipidus (oral tablets): Initially 0.1 mg 1–3 times daily. Usual range 0.2–1.2 mg daily in divided doses. Max 1.2 mg/day.\n• Primary Nocturnal Enuresis (oral lyophilisate): Initially 120 micrograms at bedtime. Max 240 micrograms at bedtime. Fluid restriction essential.\n• Haemostasis (IV): 0.3 micrograms/kg (maximum 20 micrograms) infused over 15–30 minutes. Limited to 1-2 doses due to tachyphylaxis.","preparation":"For IV administration for haemostasis: Dilute the required dose (e.g. 20 micrograms) in 50 mL 0.9% sodium chloride or 5% glucose and infuse over 15–30 minutes. The resulting concentration for 20 micrograms in 50 mL is 0.4 micrograms/mL.","contraindications":"• Known hyponatraemia or history of hyponatraemia.\n• Primary polydipsia (with urine production exceeding 40 mL/kg/24 hours).\n• Unstable cardiac insufficiency or other conditions requiring diuretic treatment (e.g. symptomatic heart failure).\n• Moderate to severe renal impairment (creatinine clearance <50 mL/minute).\n• Syndrome of Inappropriate Antidiuretic Hormone Secretion (SIADH).\n• Type IIB von Willebrand''s disease.\n• Children under 6 years for primary nocturnal enuresis.","sources":[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Desmopressin (DDAVP) — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=desmopressin"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Desmopressin (DDAVP) — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=desmopressin"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Desmopressin (DDAVP) — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=desmopressin"},{"accessed":"2026-11-01","publisher":"electronic Medicines Compendium (emc), Datapharm","reviewNote":"Selected formulation, route and population only. Other presentations, storage and treatment doses are not verified; no current stock availability certification.","scope":"4micrograms/mL desmopressin acetate equivalent to3.56micrograms/mL desmopressin, IV/IM/SC indication-specific adults/children/infants; oral forms not covered.","sections":["1","2","3","4.1","4.2"],"title":"DDAVP/Desmopressin Injection — UK SmPC","url":"https://www.medicines.org.uk/emc/product/5447/smpc"}]}'::jsonb THEN
    UPDATE public.drugs SET key_warning = 'Fluid management depends on the indication. Excess water while antidiuresis is active can cause hyponatraemia. In known cranial diabetes insipidus, interruption of desmopressin or loss of access to water can cause life-threatening dehydration and hypernatraemia. Follow the individual endocrine fluid plan.',
      adult_bolus_dose = 'The named injection (emc 5447) gives 1–4 micrograms once daily IV, IM or SC as the usual adult central-diabetes-insipidus regimen, individualised to response. See dosing for the distinct decompensated inpatient pathway.
Haemostatic use is a separate specialist indication. Named UK DDAVP 4 micrograms/mL injection (emc 5447) specifies 0.4 micrograms/kg by IV infusion over 20 minutes for selected responsive patients with mild–moderate haemophilia or von Willebrand disease undergoing surgery or after trauma. Use the regimen selected by haematology, with factor response, sodium and fluid-balance monitoring. It is contraindicated for haemostasis in type 2B von Willebrand disease.',
      dosing = 'Central diabetes insipidus (AVP deficiency): when a patient is alert with intact thirst and can safely drink, provide access to water and continue their agreed desmopressin regimen. A patient unable to drink, or with decompensated disease, needs an individual fluid plan, serial sodium and urine output, and urgent endocrine input. Correct circulatory volume depletion first. During resuscitation the Society for Endocrinology recommends sodium measurement every 4 hours. For known disease with excessive dilute urine, it describes 1–2 micrograms IV or IM with close assessment before any repeat dose.
Haemostatic use is a separate specialist indication. Named UK DDAVP 4 micrograms/mL injection (emc 5447) specifies 0.4 micrograms/kg by IV infusion over 20 minutes for selected responsive patients with mild–moderate haemophilia or von Willebrand disease undergoing surgery or after trauma. Use the regimen selected by haematology, with factor response, sodium and fluid-balance monitoring. It is contraindicated for haemostasis in type 2B von Willebrand disease.
Oral tablets, sublingual melts and injections have different strengths, doses and uses. For nocturnal enuresis use the exact oral-product instructions for bedtime dosing and fluid restriction. Never convert numerical milligram, microgram or route doses directly.',
      preparation = 'For the named UK 4 micrograms/mL DDAVP injection and its labelled haemostatic indication, dilute the selected dose in 50 mL sodium chloride 0.9% and infuse over 20 minutes. Follow the haematology prescription. The separate central-diabetes-insipidus regimen is titrated to fluid balance, serum sodium and urine output.',
      contraindications = 'The named DDAVP injection lists hypersensitivity, habitual/psychogenic polydipsia, a history of unstable angina, cardiac insufficiency or other conditions requiring diuretics, known hyponatraemia and SIADH. For haemostatic use it also lists type 2B von Willebrand disease. Oral formulations have their own renal and age restrictions.',
      sources = '[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Desmopressin (DDAVP) — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=desmopressin"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Desmopressin (DDAVP) — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=desmopressin"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Desmopressin (DDAVP) — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=desmopressin"},{"accessed":"2026-11-01","publisher":"electronic Medicines Compendium (emc), Datapharm","reviewNote":"Selected formulation, route and population only. Other presentations, storage and treatment doses are not verified; no current stock availability certification.","scope":"4micrograms/mL desmopressin acetate equivalent to3.56micrograms/mL desmopressin, IV/IM/SC indication-specific adults/children/infants; oral forms not covered.","sections":["1","2","3","4.1","4.2"],"title":"DDAVP/Desmopressin Injection — UK SmPC","url":"https://www.medicines.org.uk/emc/product/5447/smpc"},{"title":"Inpatient management of cranial diabetes insipidus: access to water, fluid replacement and parenteral desmopressin","url":"https://doi.org/10.1530/EC-18-0154","publisher":"Society for Endocrinology","accessed":"2026-11-19"}]'::jsonb WHERE id='182e4e9d-b8af-4e8c-a119-bfbafda8fb3f'::uuid AND slug='desmopressin';
  ELSE
    RAISE EXCEPTION 'Unexpected editorial drift for drug desmopressin; no changes committed';
  END IF;
  SELECT jsonb_build_object('adult_bolus_dose', d.adult_bolus_dose, 'infusion_range', d.infusion_range, 'dosing', d.dosing, 'sources', d.sources) INTO STRICT existing FROM public.drugs AS d WHERE d.id='ab99d14b-2753-4eb1-9a68-e282273bf97d'::uuid AND d.slug='midazolam' FOR UPDATE;
  IF existing = '{"adult_bolus_dose":"IV conscious sedation using the named 1 mg/mL injection: adults below 60 years usually start with 2–2.5 mg given slowly, then reassess and use small increments if needed. In older, debilitated or chronically ill adults start with 0.5–1 mg and titrate more cautiously. Totals above 5 mg and 3.5 mg respectively are usually unnecessary; they are not absolute dosing limits. Monitor circulation and ventilation and have airway rescue immediately available.\nAnaesthetic induction is a separate monitored indication. Age, premedication, opioid co-administration and clinical condition materially change dose: for example 0.15–0.2 mg/kg in a premedicated adult under 60 in the named product. Titrate slowly using the full product schedule.","infusion_range":"Adult ICU sedation, named 1 mg/mL injection (emc 3605): maintenance 0.03–0.2 mg/kg/hour, individually titrated to sedation with airway and haemodynamic monitoring. Hypovolaemia, vasoconstriction or hypothermia may require lower doses. The separate combined-anaesthesia infusion range must not be substituted for this indication.","dosing":"• Adults (IV):\nIV conscious sedation using the named 1 mg/mL injection: adults below 60 years usually start with 2–2.5 mg given slowly, then reassess and use small increments if needed. In older, debilitated or chronically ill adults start with 0.5–1 mg and titrate more cautiously. Totals above 5 mg and 3.5 mg respectively are usually unnecessary; they are not absolute dosing limits. Monitor circulation and ventilation and have airway rescue immediately available.\nAnaesthetic induction is a separate monitored indication. Age, premedication, opioid co-administration and clinical condition materially change dose: for example 0.15–0.2 mg/kg in a premedicated adult under 60 in the named product. Titrate slowly using the full product schedule.\nConvulsive status epilepticus: use the individual emergency plan and NICE NG217. In the community the first benzodiazepine may be buccal midazolam or rectal diazepam; with immediate IV access and resuscitation facilities NICE recommends IV lorazepam. Escalate according to response, timing and all prior rescue doses.\n• Paediatric (IV):\n  • IV conscious sedation: Age 6 months–5 years, initial 0.05–0.1 mg/kg, with total doses up to 0.6 mg/kg but not exceeding 6 mg. Age 6–12 years, initial 0.025–0.05 mg/kg, with total doses up to 0.4 mg/kg but not exceeding 10 mg. Give slowly and titrate; infants <6 months require a separate specialist setting. Do not apply a universal 10 mg paediatric cap or blend procedural sedation with ICU infusion regimens.\n• Paediatric (oral/buccal):\n  • Premedication (oral): 0.25-0.5 mg/kg (max 10 mg).\nBUCCOLAM oromucosal rescue in diagnosed epilepsy: the named product uses 2.5 mg from 3 months to under 1 year (3–6 months in monitored hospital care only), 5 mg from 1 to under 5 years, 7.5 mg from 5 to under 10 years and 10 mg from 10 years. The carer gives one prescribed dose, seeks emergency help if the seizure persists at 10 minutes, and seeks medical advice before repeating. This is distinct from the clinician-led status pathway.\n• Renal impairment: Dose reduction needed in severe renal insufficiency (creatinine clearance <30 mL/min) due to active metabolite accumulation. Use lower doses and titrate carefully.\n• Hepatic impairment: Elimination half-life prolonged. Use lower doses and titrate carefully, especially in severe impairment.\nAdult ICU sedation, named 1 mg/mL injection (emc 3605): maintenance 0.03–0.2 mg/kg/hour, individually titrated to sedation with airway and haemodynamic monitoring. Hypovolaemia, vasoconstriction or hypothermia may require lower doses. The separate combined-anaesthesia infusion range must not be substituted for this indication.","sources":[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Midazolam — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=midazolam"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Midazolam — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=midazolam"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Midazolam — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=midazolam"},{"accessed":"2026-10-30","publisher":"electronic Medicines Compendium (emc)","title":"Midazolam — targeted dosing/safety source (4.2; updated2026-07-28)","url":"https://www.medicines.org.uk/emc/product/3605/smpc"},{"title":"BUCCOLAM oromucosal solution: age bands, care setting and carer administration","url":"https://www.medicines.org.uk/emc/product/7460/smpc","publisher":"electronic Medicines Compendium","accessed":"2026-11-19"},{"title":"NG217: immediate treatment of convulsive status epilepticus, section 7","url":"https://www.nice.org.uk/guidance/ng217/chapter/treating-status-epilepticus-repeated-or-cluster-seizures-and-prolonged-seizures","publisher":"NICE","accessed":"2026-11-19"}]}'::jsonb THEN
    NULL;
  ELSIF existing = '{"adult_bolus_dose":"• Premedication/Conscious sedation (BNF): 1-2.5 mg IV slowly over 2-5 min, titrated to effect. Max 5 mg. Elderly/debilitated: 0.5-1 mg IV slowly, max 3.5 mg.\n• Anaesthetic induction (anaesthetic practice): 0.15-0.2 mg/kg IV. Reduce dose in elderly/frail: 0.05-0.15 mg/kg IV.","infusion_range":"• Sedation in ITU (BNF): 0.03-0.1 mg/kg/hour in patients <60 years old. Higher doses may be used in anaesthetic practice as titrated to effect.","dosing":"• Adults (IV):\n  • Conscious sedation for procedures: Initial 0.5-1 mg over 2-5 minutes, repeat 0.5-1 mg every 2-5 minutes as needed. For conscious sedation, the cited SmPC gives a usual total 3.5–7.5 mg in adults <60 years; in adults ≥60 years, debilitated or chronically ill, the total is usually below 3.5 mg. Titrate slowly to effect with cardiorespiratory monitoring.\n  • Induction of anaesthesia: 0.15-0.2 mg/kg in healthy adults (<60 years). 0.05-0.15 mg/kg in elderly/frail (>60 years).\n  • Status epilepticus: 0.15-0.2 mg/kg (max 10 mg), administered over 2-3 minutes. May be repeated once if necessary after 10-15 minutes (Resuscitation Council UK guidelines).\n• Paediatric (IV):\n  • IV conscious sedation: Age 6 months–5 years, initial 0.05–0.1 mg/kg, with total doses up to 0.6 mg/kg but not exceeding 6 mg. Age 6–12 years, initial 0.025–0.05 mg/kg, with total doses up to 0.4 mg/kg but not exceeding 10 mg. Give slowly and titrate; infants <6 months require a separate specialist setting. Do not apply a universal 10 mg paediatric cap or blend procedural sedation with ICU infusion regimens.\n• Paediatric (oral/buccal):\n  • Premedication (oral): 0.25-0.5 mg/kg (max 10 mg).\n  • Seizures (buccal): 0.2-0.3 mg/kg (max 10 mg), repeat once after 10-15 minutes if necessary. Max total 20 mg.\n• Renal impairment: Dose reduction needed in severe renal insufficiency (creatinine clearance <30 mL/min) due to active metabolite accumulation. Use lower doses and titrate carefully.\n• Hepatic impairment: Elimination half-life prolonged. Use lower doses and titrate carefully, especially in severe impairment.","sources":[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Midazolam — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=midazolam"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Midazolam — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=midazolam"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Midazolam — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=midazolam"},{"accessed":"2026-10-30","publisher":"electronic Medicines Compendium (emc)","title":"Midazolam — targeted dosing/safety source (4.2; updated2026-07-28)","url":"https://www.medicines.org.uk/emc/product/3605/smpc"}]}'::jsonb THEN
    UPDATE public.drugs SET adult_bolus_dose = 'IV conscious sedation using the named 1 mg/mL injection: adults below 60 years usually start with 2–2.5 mg given slowly, then reassess and use small increments if needed. In older, debilitated or chronically ill adults start with 0.5–1 mg and titrate more cautiously. Totals above 5 mg and 3.5 mg respectively are usually unnecessary; they are not absolute dosing limits. Monitor circulation and ventilation and have airway rescue immediately available.
Anaesthetic induction is a separate monitored indication. Age, premedication, opioid co-administration and clinical condition materially change dose: for example 0.15–0.2 mg/kg in a premedicated adult under 60 in the named product. Titrate slowly using the full product schedule.',
      infusion_range = 'Adult ICU sedation, named 1 mg/mL injection (emc 3605): maintenance 0.03–0.2 mg/kg/hour, individually titrated to sedation with airway and haemodynamic monitoring. Hypovolaemia, vasoconstriction or hypothermia may require lower doses. The separate combined-anaesthesia infusion range must not be substituted for this indication.',
      dosing = '• Adults (IV):
IV conscious sedation using the named 1 mg/mL injection: adults below 60 years usually start with 2–2.5 mg given slowly, then reassess and use small increments if needed. In older, debilitated or chronically ill adults start with 0.5–1 mg and titrate more cautiously. Totals above 5 mg and 3.5 mg respectively are usually unnecessary; they are not absolute dosing limits. Monitor circulation and ventilation and have airway rescue immediately available.
Anaesthetic induction is a separate monitored indication. Age, premedication, opioid co-administration and clinical condition materially change dose: for example 0.15–0.2 mg/kg in a premedicated adult under 60 in the named product. Titrate slowly using the full product schedule.
Convulsive status epilepticus: use the individual emergency plan and NICE NG217. In the community the first benzodiazepine may be buccal midazolam or rectal diazepam; with immediate IV access and resuscitation facilities NICE recommends IV lorazepam. Escalate according to response, timing and all prior rescue doses.
• Paediatric (IV):
  • IV conscious sedation: Age 6 months–5 years, initial 0.05–0.1 mg/kg, with total doses up to 0.6 mg/kg but not exceeding 6 mg. Age 6–12 years, initial 0.025–0.05 mg/kg, with total doses up to 0.4 mg/kg but not exceeding 10 mg. Give slowly and titrate; infants <6 months require a separate specialist setting. Do not apply a universal 10 mg paediatric cap or blend procedural sedation with ICU infusion regimens.
• Paediatric (oral/buccal):
  • Premedication (oral): 0.25-0.5 mg/kg (max 10 mg).
BUCCOLAM oromucosal rescue in diagnosed epilepsy: the named product uses 2.5 mg from 3 months to under 1 year (3–6 months in monitored hospital care only), 5 mg from 1 to under 5 years, 7.5 mg from 5 to under 10 years and 10 mg from 10 years. The carer gives one prescribed dose, seeks emergency help if the seizure persists at 10 minutes, and seeks medical advice before repeating. This is distinct from the clinician-led status pathway.
• Renal impairment: Dose reduction needed in severe renal insufficiency (creatinine clearance <30 mL/min) due to active metabolite accumulation. Use lower doses and titrate carefully.
• Hepatic impairment: Elimination half-life prolonged. Use lower doses and titrate carefully, especially in severe impairment.
Adult ICU sedation, named 1 mg/mL injection (emc 3605): maintenance 0.03–0.2 mg/kg/hour, individually titrated to sedation with airway and haemodynamic monitoring. Hypovolaemia, vasoconstriction or hypothermia may require lower doses. The separate combined-anaesthesia infusion range must not be substituted for this indication.',
      sources = '[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Midazolam — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=midazolam"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Midazolam — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=midazolam"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Midazolam — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=midazolam"},{"accessed":"2026-10-30","publisher":"electronic Medicines Compendium (emc)","title":"Midazolam — targeted dosing/safety source (4.2; updated2026-07-28)","url":"https://www.medicines.org.uk/emc/product/3605/smpc"},{"title":"BUCCOLAM oromucosal solution: age bands, care setting and carer administration","url":"https://www.medicines.org.uk/emc/product/7460/smpc","publisher":"electronic Medicines Compendium","accessed":"2026-11-19"},{"title":"NG217: immediate treatment of convulsive status epilepticus, section 7","url":"https://www.nice.org.uk/guidance/ng217/chapter/treating-status-epilepticus-repeated-or-cluster-seizures-and-prolonged-seizures","publisher":"NICE","accessed":"2026-11-19"}]'::jsonb WHERE id='ab99d14b-2753-4eb1-9a68-e282273bf97d'::uuid AND slug='midazolam';
  ELSE
    RAISE EXCEPTION 'Unexpected editorial drift for drug midazolam; no changes committed';
  END IF;
  SELECT jsonb_build_object('adult_bolus_dose', d.adult_bolus_dose, 'dosing', d.dosing, 'infusion_range', d.infusion_range, 'preparation', d.preparation, 'presentation', d.presentation, 'key_warning', d.key_warning, 'sources', d.sources) INTO STRICT existing FROM public.drugs AS d WHERE d.id='92acc0b2-61db-4dcd-97bb-949a0673c79a'::uuid AND d.slug='cisatracurium' FOR UPDATE;
  IF existing = '{"adult_bolus_dose":"Named UK 2 mg/mL injection (emc 2595): recommended tracheal-intubation dose for adults and children aged 1 month to 12 years is 0.15 mg/kg IV. Lower paediatric doses studied when intubation is not required are a separate indication. Provide anaesthesia, ventilation and quantitative neuromuscular monitoring.\nIn adults the usual maintenance bolus is 0.03 mg/kg, adjusted to measured neuromuscular block.","dosing":"Named UK 2 mg/mL injection (emc 2595): recommended tracheal-intubation dose for adults and children aged 1 month to 12 years is 0.15 mg/kg IV. Lower paediatric doses studied when intubation is not required are a separate indication. Provide anaesthesia, ventilation and quantitative neuromuscular monitoring.\nAdult surgery and children aged 2–12 years: following signs of recovery, the labelled initial infusion rate is 3 micrograms/kg/minute; after stabilisation, 1–2 micrograms/kg/minute usually maintains the intended block. Adult ICU has a separate regimen beginning at 3 micrograms/kg/minute with wide individual variation. Titrate to monitored block and clinical context.\nThis named product does not recommend use below 1 month of age. Separate specialist guidance is required.","infusion_range":"Adult surgery and children aged 2–12 years: following signs of recovery, the labelled initial infusion rate is 3 micrograms/kg/minute; after stabilisation, 1–2 micrograms/kg/minute usually maintains the intended block. Adult ICU has a separate regimen beginning at 3 micrograms/kg/minute with wide individual variation. Titrate to monitored block and clinical context.","preparation":"For the named 2 mg/mL product, an infused preparation of 1 mg/mL can be made with 50 mg (25 mL of 2 mg/mL) and compatible diluent to a FINAL 50 mL. Verify the actual labelled syringe concentration and local protocol. The SmPC describes compatible chloride/glucose diluents and physical/chemical stability across 0.1–2 mg/mL. Prepare immediately before use and follow the microbiological in-use limits. Do not mix with propofol emulsion or alkaline solutions, including thiopentone.","presentation":"Named emc 2595 contains cisatracurium 2 mg/mL. Other strengths and brands have separate product instructions. Store this product at 2–8°C in the original packaging and protect from light; use the exact manufacturer’s expiry/in-use directions.","key_warning":"Cisatracurium causes paralysis and does not provide unconsciousness or analgesia. Provide anaesthesia or sedation, ventilatory support and quantitative neuromuscular monitoring. Sugammadex does not reverse cisatracurium.","sources":[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Cisatracurium — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=cisatracurium"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Cisatracurium — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=cisatracurium"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Cisatracurium — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=cisatracurium"},{"accessed":"2026-09-13","publisher":"Association of Anaesthetists","title":"Recommendations for standards of monitoring during anaesthesia and recovery 2021","url":"https://doi.org/10.1111/anae.15501"},{"title":"Cisatracurium 2 mg/mL: paediatric tracheal intubation, perioperative/ICU infusion, stability and dilution","url":"https://www.medicines.org.uk/emc/product/2595/smpc","publisher":"electronic Medicines Compendium","accessed":"2026-11-19"}]}'::jsonb THEN
    NULL;
  ELSIF existing = '{"adult_bolus_dose":"• Adult Intubation: 0.15 mg/kg IV. For rapid intubation, up to 0.2 mg/kg IV (anaesthetic practice).\n• Adult Maintenance: 0.03 mg/kg IV. Administer when twitch response is 10% of control or 1-2 twitches on TOF.","dosing":"• Adult (Intubation): 0.15 mg/kg IV (routine intubation) or 0.2 mg/kg IV for rapid onset (anaesthetic practice).\n• Adult (Maintenance): 0.03 mg/kg IV bolus or titrate infusion.\n• Paediatric (1 month to 12 years): 0.1 mg/kg IV initially.\n• Neonates/Infants (<1 month): Insufficient data to recommend. Use only if potential benefit outweighs risk.\n• Elderly/Renal/Hepatic: No dose adjustment usually required. Onset may be slightly slower in elderly and severe renal impairment. Duration may be prolonged in severe hepatic impairment.","infusion_range":"• Adults: Initially 3 micrograms/kg/minute (0.18 mg/kg/hour). Range typically 0.5–10 micrograms/kg/minute (0.03-0.6 mg/kg/hour).\n• Children (2–12 years): Initially 3 micrograms/kg/minute. Range typically 0.5–10 micrograms/kg/minute.\n• ITU patients: Initial rate 0.1-0.2 mg/kg/hour, titrate to effect. Typical maintenance 0.03-0.18 mg/kg/hour (0.5–3 micrograms/kg/minute).","preparation":"• Bolus: Administer neat (2 mg/mL or 5 mg/mL).\n• Infusion: Dilute to 0.1–0.4 mg/mL using 0.9% sodium chloride, 5% glucose, or 0.18% sodium chloride and 4% glucose. Example: 20 mg (10 mL of 2 mg/mL) in 40 mL diluent yields 0.4 mg/mL. Stable for 24 hours at 5–25°C. Incompatible with alkaline solutions (e.g. thiopental, propofol) and solutions with pH > 7.5.","presentation":"Vials of 2 mg/mL (2.5 mL, 5 mL, 10 mL) or 5 mg/mL (20 mL, 30 mL). Clear, colourless to pale yellowish-green solution. Store refrigerated (2–8°C) and protect from light. Stable for 21 days at 25°C.","key_warning":"Cisatracurium is primarily cleared via Hofmann elimination, making sugammadex an ineffective reversal agent.","sources":[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Cisatracurium — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=cisatracurium"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Cisatracurium — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=cisatracurium"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Cisatracurium — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=cisatracurium"},{"accessed":"2026-09-13","publisher":"Association of Anaesthetists","title":"Recommendations for standards of monitoring during anaesthesia and recovery 2021","url":"https://doi.org/10.1111/anae.15501"}]}'::jsonb THEN
    UPDATE public.drugs SET adult_bolus_dose = 'Named UK 2 mg/mL injection (emc 2595): recommended tracheal-intubation dose for adults and children aged 1 month to 12 years is 0.15 mg/kg IV. Lower paediatric doses studied when intubation is not required are a separate indication. Provide anaesthesia, ventilation and quantitative neuromuscular monitoring.
In adults the usual maintenance bolus is 0.03 mg/kg, adjusted to measured neuromuscular block.',
      dosing = 'Named UK 2 mg/mL injection (emc 2595): recommended tracheal-intubation dose for adults and children aged 1 month to 12 years is 0.15 mg/kg IV. Lower paediatric doses studied when intubation is not required are a separate indication. Provide anaesthesia, ventilation and quantitative neuromuscular monitoring.
Adult surgery and children aged 2–12 years: following signs of recovery, the labelled initial infusion rate is 3 micrograms/kg/minute; after stabilisation, 1–2 micrograms/kg/minute usually maintains the intended block. Adult ICU has a separate regimen beginning at 3 micrograms/kg/minute with wide individual variation. Titrate to monitored block and clinical context.
This named product does not recommend use below 1 month of age. Separate specialist guidance is required.',
      infusion_range = 'Adult surgery and children aged 2–12 years: following signs of recovery, the labelled initial infusion rate is 3 micrograms/kg/minute; after stabilisation, 1–2 micrograms/kg/minute usually maintains the intended block. Adult ICU has a separate regimen beginning at 3 micrograms/kg/minute with wide individual variation. Titrate to monitored block and clinical context.',
      preparation = 'For the named 2 mg/mL product, an infused preparation of 1 mg/mL can be made with 50 mg (25 mL of 2 mg/mL) and compatible diluent to a FINAL 50 mL. Verify the actual labelled syringe concentration and local protocol. The SmPC describes compatible chloride/glucose diluents and physical/chemical stability across 0.1–2 mg/mL. Prepare immediately before use and follow the microbiological in-use limits. Do not mix with propofol emulsion or alkaline solutions, including thiopentone.',
      presentation = 'Named emc 2595 contains cisatracurium 2 mg/mL. Other strengths and brands have separate product instructions. Store this product at 2–8°C in the original packaging and protect from light; use the exact manufacturer’s expiry/in-use directions.',
      key_warning = 'Cisatracurium causes paralysis and does not provide unconsciousness or analgesia. Provide anaesthesia or sedation, ventilatory support and quantitative neuromuscular monitoring. Sugammadex does not reverse cisatracurium.',
      sources = '[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Cisatracurium — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=cisatracurium"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Cisatracurium — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=cisatracurium"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Cisatracurium — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=cisatracurium"},{"accessed":"2026-09-13","publisher":"Association of Anaesthetists","title":"Recommendations for standards of monitoring during anaesthesia and recovery 2021","url":"https://doi.org/10.1111/anae.15501"},{"title":"Cisatracurium 2 mg/mL: paediatric tracheal intubation, perioperative/ICU infusion, stability and dilution","url":"https://www.medicines.org.uk/emc/product/2595/smpc","publisher":"electronic Medicines Compendium","accessed":"2026-11-19"}]'::jsonb WHERE id='92acc0b2-61db-4dcd-97bb-949a0673c79a'::uuid AND slug='cisatracurium';
  ELSE
    RAISE EXCEPTION 'Unexpected editorial drift for drug cisatracurium; no changes committed';
  END IF;
  SELECT jsonb_build_object('indication_oneliner', d.indication_oneliner, 'adult_bolus_dose', d.adult_bolus_dose, 'infusion_range', d.infusion_range, 'dosing', d.dosing, 'preparation', d.preparation, 'infusion_standard', d.infusion_standard, 'contraindications', d.contraindications, 'sources', d.sources) INTO STRICT existing FROM public.drugs AS d WHERE d.id='6064c64e-0c88-456d-b4c5-cf7ecadcb543'::uuid AND d.slug='phenylephrine' FOR UPDATE;
  IF existing = '{"indication_oneliner":"Adult hypotension during spinal, epidural or general anaesthesia (named Unimedic 10 mg/mL concentrate).","adult_bolus_dose":"For adult hypotension during spinal, epidural or general anaesthesia: named Unimedic 10 mg/mL concentrate requires dilution. Start with 50–100 micrograms IV per bolus and reassess pressure and heart rate before repeating, per this product.","infusion_range":"For this named product in adult anaesthetic hypotension: initial IV infusion commonly 25–50 micrograms/minute. Rates of 25–100 micrograms/minute have been evaluated. The label advises changing to another vasopressor if more than 50 micrograms/minute is required or reflex bradycardia develops. Use continuous haemodynamic assessment and the local anaesthetic protocol.","dosing":"For adult hypotension during spinal, epidural or general anaesthesia: named Unimedic 10 mg/mL concentrate requires dilution. Start with 50–100 micrograms IV per bolus and reassess pressure and heart rate before repeating, per this product.\nFor this named product in adult anaesthetic hypotension: initial IV infusion commonly 25–50 micrograms/minute. Rates of 25–100 micrograms/minute have been evaluated. The label advises changing to another vasopressor if more than 50 micrograms/minute is required or reflex bradycardia develops. Use continuous haemodynamic assessment and the local anaesthetic protocol.\nFor acute tachyarrhythmia, follow the current RCUK algorithm. Phenylephrine is not included as a routine SVT treatment. Paediatric safety and efficacy have not been established for the named product.","preparation":"For the named 10 mg/mL concentrate, prepare to a final concentration in accordance with the label and local policy. 1 mL contains 10 mg; 10 mg in a FINAL 100 mL gives 100 micrograms/mL, and in a FINAL 200 mL gives 50 micrograms/mL. Use the actual verified syringe concentration in any calculation. Commercial ready-to-use products of different strengths have separate instructions.","infusion_standard":{"amount_mg":10,"diluent_ml":100,"unit":"mcg/min","weight_based":false,"note":"Named-product example: 10 mg in a FINAL 100 mL = 100 micrograms/mL; confirm the label."},"contraindications":"For the named Unimedic product: hypersensitivity, severe hypertension or peripheral vascular disease, severe hyperthyroidism and concurrent non-selective MAO inhibitor use or the two weeks following withdrawal. Review the product-specific precautions in cardiovascular disease and monitor for ischaemia, hypertension and bradycardia.","sources":[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Phenylephrine — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=phenylephrine"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Phenylephrine — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=phenylephrine"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Phenylephrine — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=phenylephrine"},{"accessed":"2026-09-13","publisher":"Critical Care Medicine / SCCM–ESICM","title":"Surviving Sepsis Campaign: International Guidelines for Management of Sepsis and Septic Shock 2021","url":"https://doi.org/10.1097/CCM.0000000000005337"},{"title":"Phenylephrine Unimedic 10 mg/mL concentrate: indications, doses, contraindications and dilution","url":"https://www.medicines.org.uk/emc/product/10818/smpc","publisher":"electronic Medicines Compendium","accessed":"2026-11-19"},{"title":"Adult advanced life support guidelines 2025: peri-arrest tachyarrhythmia","url":"https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/adult-advanced-life-support-guidelines","publisher":"Resuscitation Council UK","accessed":"2026-11-19"}]}'::jsonb THEN
    NULL;
  ELSIF existing = '{"indication_oneliner":"Acute hypotension (e.g. during anaesthesia, spinal block); paroxysmal supraventricular tachycardia (PSVT).","adult_bolus_dose":"• Acute hypotension: IV bolus 50–100 micrograms (anaesthetic practice) or 100–500 micrograms. Titrate to effect. Max single dose 500 micrograms.\n• PSVT: Rapid IV bolus of 500 micrograms. Repeat after 2–3 minutes if required, maximum single dose 1 mg.","infusion_range":"IV infusion: 35–180 micrograms/minute, titrated to effect. Higher doses up to 6 micrograms/kg/minute may be used in critical care settings.","dosing":"• Adults (hypotension): IV bolus 50–100 micrograms (anaesthetic practice) or 100–500 micrograms. Titrate to effect; maximum single dose 500 micrograms. IV infusion initially 35–70 micrograms/minute, adjusted according to response, up to 180 micrograms/minute. Higher doses may be used in critical care (e.g. 0.5–1 micrograms/kg/minute up to 6 micrograms/kg/minute).\n• Adults (PSVT): Rapid IV bolus of 500 micrograms. Repeat after 2–3 minutes if required, maximum single dose 1 mg.\n• Paediatrics: Not generally recommended; specialist advice and strict monitoring essential. If used, 0.5-1 microgram/kg IV bolus. Limited data.\n• Elderly: Lower initial doses; increased risk of adverse effects.","preparation":"• Bolus: 10 mg (1 mL) diluted with 0.9% sodium chloride to 100 mL = 100 micrograms/mL.\n• Infusion: 20 mg (2 mL) diluted with 5% glucose or 0.9% sodium chloride to 50 mL = 400 micrograms/mL. For example, 40 mg (4 mL) in 50 mL = 800 micrograms/mL.","infusion_standard":{"amount_mg":10,"diluent_ml":50,"unit":"mcg/min","weight_based":false},"contraindications":"• Hypersensitivity to phenylephrine.\n• Severe hypertension or ventricular tachycardia.\n• Severe peripheral vascular disease.\n• Co-administration with MAOIs or within 14 days of stopping MAOI therapy.\n• Hyperthyroidism, phaeochromocytoma.\n• Severe coronary artery disease.\n• Narrow-angle glaucoma.\n• History of aneurysms.\n• Tachycardia.","sources":[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Phenylephrine — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=phenylephrine"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Phenylephrine — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=phenylephrine"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Phenylephrine — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=phenylephrine"},{"accessed":"2026-09-13","publisher":"Critical Care Medicine / SCCM–ESICM","title":"Surviving Sepsis Campaign: International Guidelines for Management of Sepsis and Septic Shock 2021","url":"https://doi.org/10.1097/CCM.0000000000005337"}]}'::jsonb THEN
